/**
 * Spectrum Workflow icon custom elements — no bare-specifier dependencies.
 * Registers sp-icon-dashboard, sp-icon-document, sp-icon-settings,
 * sp-icon-user, sp-icon-refresh, sp-icon-chevron-down, sp-icon-chevron-up,
 * sp-icon-alert, sp-icon-location as custom elements that render SVG in
 * shadow DOM with fill:currentColor, compatible with SWC sp-action-button
 * and sp-button slot="icon".
 */

function defineIcon(tag, svgInner) {
  if (customElements.get(tag)) return;
  class SpIcon extends HTMLElement {
    constructor() {
      super();
      const shadow = this.attachShadow({ mode: 'open' });
      shadow.innerHTML = `<style>:host{display:inline-flex;width:18px;height:18px;color:inherit;}svg{fill:currentColor;width:100%;height:100%;}</style><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 36 36" aria-hidden="true">${svgInner}</svg>`;
    }
  }
  customElements.define(tag, SpIcon);
}

